namespace sv_bfb0c527c5bc4c6e91ba28d178e77511.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeState
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0078d4";
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Any component can inject this, read/write state, and call NotifyChanged().
/// Subscribers receive updates via the OnChange event.
/// </summary>
public class ThemeService
{
    private readonly ThemeState _state = new();

    public Theme CurrentTheme => _state.Theme;
    public string AccentColor => _state.AccentColor;

    public event Action? OnChange;

    public void SetTheme(Theme theme)
    {
        _state.Theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        _state.AccentColor = color;
        OnChange?.Invoke();
    }

    public void SetAll(Theme theme, string accentColor)
    {
        _state.Theme = theme;
        _state.AccentColor = accentColor;
        OnChange?.Invoke();
    }
}

