@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="settings-panel">
    <h3>Theme</h3>
    <div class="theme-options">
        @foreach (var theme in Enum.GetValues<Theme>())
        {
            <button class="btn @(ThemeService.CurrentTheme == theme ? "btn-primary" : "btn-outline-secondary")"
                    @onclick="() => SelectTheme(theme)">
                @theme
            </button>
        }
    </div>

    <h3 class="mt-4">Accent Color</h3>
    <div class="accent-options">
        <input type="color" value="@ThemeService.AccentColor" @onchange="ChangeAccentColor" />
        <span class="ms-2">@ThemeService.AccentColor</span>
    </div>
</div>

<div class="mt-4">
    <strong>Current:</strong> @ThemeService.CurrentTheme theme with accent @ThemeService.AccentColor
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void SelectTheme(Theme theme)
    {
        ThemeService.SetTheme(theme);
    }

    private void ChangeAccentColor(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0078d4");
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

